import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, let x, y, z be positive real numbers and let k be a fixed positive integer. Suppose they satisfy the cyclic relation ((x^(2{k}) - 1)(y^(2{k}) - 1))/(x^{k} y^{k}) + ((x^(2{k}) - 1)(z^(2{k}) - 1))/(x^{k} z^{k}) + ((y^(2{k}) - 1)(z^(2{k}) - 1))/(y^{k} z^{k}) = 4, together with the non-degeneracy condition x^{k} y^{k} + x^{k} z^{k} + y^{k} z^{k} != 1. Determine the minimum value of F = {b}^2 * x^(2{k}) + ({a}^2) * ({b}^4) * (y^{k} z^{k})^2 - 2 * ({a}^2) * ({b}^4) * (y^{k} z^{k}) + ({a}^4) / (y^{k} + z^{k})^2 over all such triples (x, y, z).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose k >= 2 to ensure a genuine generalization beyond the seed.
k = rng.randint(2, 5)
# Choose a moderately large 'a' to create nontrivial coefficients.
a_choices = [7, 11, 13, 17, 19, 23]
a = rng.choice(a_choices)
# Choose b in {2,3,4} to keep coefficients large but manageable and ensure nontrivial minimum.
b = rng.choice([2, 3, 4])
return {'k': int(k), 'a': int(a), 'b': int(b)}

    def verifier(assign):
# Validate input
if not all(key in assign for key in ('k','a','b')):
    # Missing data
    return (False, None)  # required keys absent
k = assign['k']
a = assign['a']
b = assign['b']
# Basic type and domain checks
if not (isinstance(k, int) and isinstance(a, int) and isinstance(b, int)):
    return (False, None)  # types must be integers
if k < 2 or a <= 0 or b <= 0:
    return (False, None)  # enforce nontriviality and positivity
if b == 1:
    return (False, None)  # would make the bound trivial; enforce difficulty
# For this family, the minimum value can be derived in closed form as a^2 * b^2 * (3 - b^2)
answer = a*a * b*b * (3 - b*b)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
